 * (codi nou, dos caràcters ASCII). Les taules són les de Pan Docs (`The_Cartridge_Header.md`, gbdev/pandocs); no s'ha escrit cap codi de memòria.
 */
object EditorsGb {
    private val NOU = mapOf("01" to "Nintendo Research & Development 1", "08" to "Capcom", "13" to "EA (Electronic Arts)", "18" to "Hudson Soft", "19" to "B-AI", "20" to "KSS", "22" to "Planning Office WADA", "24" to "PCM Complete", "25" to "San-X", "28" to "Kemco", "29" to "SETA Corporation", "30" to "Viacom", "31" to "Nintendo", "32" to "Bandai", "33" to "Ocean Software/Acclaim Entertainment", "34" to "Konami", "35" to "HectorSoft", "37" to "Taito", "38" to "Hudson Soft", "39" to "Banpresto", "41" to "Ubi Soft", "42" to "Atlus", "44" to "Malibu Interactive", "46" to "Angel", "47" to "Bullet-Proof Software", "49" to "Irem", "50" to "Absolute", "51" to "Acclaim Entertainment", "52" to "Activision", "53" to "Sammy USA Corporation", "54" to "Konami", "55" to "Hi Tech Expressions", "56" to "LJN", "57" to "Matchbox", "58" to "Mattel", "59" to "Milton Bradley Company", "60" to "Titus Interactive", "61" to "Virgin Games Ltd.", "64" to "Lucasfilm Games", "67" to "Ocean Software", "69" to "EA (Electronic Arts)", "70" to "Infogrames", "71" to "Interplay Entertainment", "72" to "Broderbund", "73" to "Sculptured Software", "75" to "The Sales Curve Limited", "78" to "THQ", "79" to "Accolade", "80" to "Misawa Entertainment", "83" to "LOZC G.", "86" to "Tokuma Shoten", "87" to "Tsukuda Original", "91" to "Chunsoft Co.", "92" to "Video System", "93" to "Ocean Software/Acclaim Entertainment", "95" to "Varie", "96" to "Yonezawa/S'Pal", "97" to "Kaneko", "99" to "Pack-In-Video", "9H" to "Bottom Up", "A4" to "Konami (Yu-Gi-Oh!)", "BL" to "MTO", "DK" to "Kodansha")
    private val ANTIC = mapOf("01" to "Nintendo", "08" to "Capcom", "09" to "HOT-B", "0A" to "Jaleco", "0B" to "Coconuts Japan", "0C" to "Elite Systems", "13" to "EA (Electronic Arts)", "18" to "Hudson Soft", "19" to "ITC Entertainment", "1A" to "Yanoman", "1D" to "Japan Clary", "1F" to "Virgin Games Ltd.", "24" to "PCM Complete", "25" to "San-X", "28" to "Kemco", "29" to "SETA Corporation", "30" to "Infogrames", "31" to "Nintendo", "32" to "Bandai", "34" to "Konami", "35" to "HectorSoft", "38" to "Capcom", "39" to "Banpresto", "3C" to "Entertainment Interactive (stub)", "3E" to "Gremlin", "41" to "Ubi Soft", "42" to "Atlus", "44" to "Malibu Interactive", "46" to "Angel", "47" to "Spectrum HoloByte", "49" to "Irem", "4A" to "Virgin Games Ltd.", "4D" to "Malibu Interactive", "4F" to "U.S. Gold", "50" to "Absolute", "51" to "Acclaim Entertainment", "52" to "Activision", "53" to "Sammy USA Corporation", "54" to "GameTek", "55" to "Park Place", "56" to "LJN", "57" to "Matchbox", "59" to "Milton Bradley Company", "5A" to "Mindscape", "5B" to "Romstar", "5C" to "Naxat Soft", "5D" to "Tradewest", "60" to "Titus Interactive", "61" to "Virgin Games Ltd.", "67" to "Ocean Software", "69" to "EA (Electronic Arts)", "6E" to "Elite Systems", "6F" to "Electro Brain", "70" to "Infogrames", "71" to "Interplay Entertainment", "72" to "Broderbund", "73" to "Sculptured Software", "75" to "The Sales Curve Limited", "78" to "THQ", "79" to "Accolade", "7A" to "Triffix Entertainment", "7C" to "MicroProse", "7F" to "Kemco", "80" to "Misawa Entertainment", "83" to "LOZC G.", "86" to "Tokuma Shoten", "8B" to "Bullet-Proof Software", "8C" to "Vic Tokai Corp.", "8E" to "Ape Inc.", "8F" to "I'Max", "91" to "Chunsoft Co.", "92" to "Video System", "93" to "Tsubaraya Productions", "95" to "Varie", "96" to "Yonezawa/S'Pal", "97" to "Kemco", "99" to "Arc", "9A" to "Nihon Bussan", "9B" to "Tecmo", "9C" to "Imagineer", "9D" to "Banpresto", "9F" to "Nova", "A1" to "Hori Electric", "A2" to "Bandai", "A4"