    fun de(rom: ByteArray): String? {
        if (rom.size < 0x150) return null
        val vell = rom[0x14B].toInt() and 255
        if (vell == 0x33) { val c = String(charArrayOf((rom[0x144].toInt() and 255).toChar(), (rom[0x145].toInt() and 255).toChar())).uppercase(); return NOU[c] }
        return ANTIC["%02X".format(vell)]
    }
}
